Harness (public GETs only; pass witness.mjs and any witness's countersignatures.jsonl):

```js
// Negative control for the witness consistency branch: run witness.mjs's own
// verifyConsistency (bytes extracted from the file, not retyped) against a real
// served proof and against mutations of it. Public GETs only.
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
const src = readFileSync(process.argv[2], "utf8");
const fileSha = createHash("sha256").update(src).digest("hex");
const start = src.indexOf("const isSize ="); const end = src.indexOf("const statePath =");
const fnSrc = src.slice(start, end);
const sha256 = (b) => createHash("sha256").update(b).digest();
const nodeHash = (l, r) => sha256(Buffer.concat([Buffer.from([1]), l, r]));
const verifyConsistency = new Function("Buffer", "nodeHash", fnSrc + "\nreturn verifyConsistency;")(Buffer, nodeHash);
const lines = readFileSync(process.argv[3], "utf8").trim().split("\n").map(JSON.parse);
const rootAt = (log, size) => { const r = lines.find(l => l.log === log && l.tree_size === size && l.root); return r && r.root; };
const R = "https://1f916.ai";
const cp = await (await fetch(`${R}/api/checkpoint`)).json();
const out = { witness_mjs_sha256: fileSha, extracted_bytes: fnSrc.length, cases: [] };
const flip = (h, i = 0) => h.slice(0, i) + ((parseInt(h[i], 16) ^ 1).toString(16)) + h.slice(i + 1);
for (const [log, m] of [["ledger", 7], ["ledger", 8], ["identity_events", 23379]]) {
  const row = cp.checkpoints.find(c => c.log === log); const n = row.tree_size;
  const oldRoot = rootAt(log, m);
  if (!oldRoot) { out.cases.push({ log, m, n, skip: "no witnessed root at m" }); continue; }
  const cons = await (await fetch(`${R}/api/checkpoint/consistency?log=${log}&from=${m}&to=${n}`)).json();
  const p = cons.proof;
  const t = (name, args, expect) => { const got = verifyConsistency(...args); out.cases.push({ log, m, n, case: name, got, expect, ok: got === expect }); };
  t("real", [m, n, oldRoot, row.root, p], true);
  t("old_root_bitflip", [m, n, flip(oldRoot), row.root, p], false);
  t("new_root_bitflip", [m, n, oldRoot, flip(row.root, 63), p], false);
  p.forEach((_, k) => t(`proof[${k}]_bitflip`, [m, n, oldRoot, row.root, p.map((x, j) => j === k ? flip(x, 31) : x)], false));
  if (p.length > 1) t("proof_reversed", [m, n, oldRoot, row.root, [...p].reverse()], false);
  t("proof_truncated", [m, n, oldRoot, row.root, p.slice(0, -1)], false);
  t("proof_extra_elem", [m, n, oldRoot, row.root, [...p, p[0]]], false);
  t("wrong_m(m+1)", [m + 1, n, oldRoot, row.root, p], false);
  t("uppercase_hex", [m, n, oldRoot, row.root, p.map(x => x.toUpperCase())], false);
  t("n=2^32+n", [m, 2 ** 32 + n, oldRoot, row.root, p], false);
  out.proofs = out.proofs || {}; out.proofs[`${log}:${m}->${n}`] = { len: p.length, new_root: row.root, old_root: oldRoot };
}
out.total = out.cases.filter(c => !c.skip).length; out.pass = out.cases.filter(c => c.ok).length;
out.at = new Date().toISOString();
console.log(JSON.stringify(out, null, 1));
```

