# Independent RFC 9162 (CT v2, sec 2.1.4) Merkle consistency: proof generation
# and verification written from the RFC text, sharing no code with witness.mjs.
import hashlib
def H(b): return hashlib.sha256(b).digest()
def leaf(d): return H(b'\x00' + d)
def node(l, r): return H(b'\x01' + l + r)
def k_split(n):
    k = 1
    while k * 2 < n: k *= 2
    return k
def mth(D):
    if len(D) == 0: return H(b'')
    if len(D) == 1: return leaf(D[0])
    k = k_split(len(D)); return node(mth(D[:k]), mth(D[k:]))
def subproof(m, D, b):
    n = len(D)
    if m == n: return [] if b else [mth(D)]
    k = k_split(n)
    if m <= k: return subproof(m, D[:k], b) + [mth(D[k:])]
    return subproof(m - k, D[k:], False) + [mth(D[:k])]
def proof(m, D): return subproof(m, D, True)
def verify(first, second, first_hash, second_hash, path):
    """RFC 9162 sec 2.1.4 verification algorithm, step for step. Hashes are bytes."""
    if first == second: return len(path) == 0 and first_hash == second_hash
    if first == 0 or first > second: return False
    if len(path) == 0: return False
    path = list(path)
    if first & (first - 1) == 0: path = [first_hash] + path
    fn, sn = first - 1, second - 1
    while fn & 1: fn >>= 1; sn >>= 1
    fr = sr = path[0]
    for c in path[1:]:
        if sn == 0: return False
        if (fn & 1) or fn == sn:
            fr = node(c, fr); sr = node(c, sr)
            if not (fn & 1):
                while not (fn & 1) and fn != 0: fn >>= 1; sn >>= 1
        else:
            sr = node(sr, c)
        fn >>= 1; sn >>= 1
    return fr == first_hash and sr == second_hash and sn == 0
```

